import re


_SECTION_RE = re.compile(r"^\[([^]]*)\]$")
_INTERP_RE = re.compile(r"\$\{([^}]*)\}")


def _strip_inline_comment(line: str) -> str:
    """Remove an inline comment (' ;' or ' #') unless inside double quotes."""
    in_quotes = False
    i = 0
    n = len(line)
    while i < n:
        ch = line[i]
        if ch == '"':
            in_quotes = not in_quotes
        elif not in_quotes and ch in ";#" and i > 0 and line[i - 1] in " \t":
            return line[:i]
        i += 1
    return line


def _extract_value(raw_value: str) -> str:
    """Apply inline-comment removal, unquoting, and stripping to a raw value."""
    value = _strip_inline_comment(raw_value).strip()
    if len(value) >= 2 and value.startswith('"') and value.endswith('"'):
        return value[1:-1]
    return value


def parse_ini(text: str) -> dict[str, dict[str, str]]:
    sections: dict[str, dict[str, str]] = {}
    current: str | None = None
    last_key: str | None = None

    for raw_line in text.splitlines():
        stripped = raw_line.strip()

        # Rule 3: blank lines and full-line comments are ignored.
        if not stripped or stripped[0] in ";#":
            continue

        # Rule 1: section header (surrounding whitespace allowed).
        match = _SECTION_RE.match(stripped)
        if match:
            current = match.group(1).strip()
            sections.setdefault(current, {})
            last_key = None
            continue

        # Rule 6: continuation line (starts with whitespace).
        if raw_line[:1] in " \t":
            if current is None:
                raise ValueError(
                    f"continuation line before any section: {raw_line!r}"
                )
            if last_key is None:
                raise ValueError(
                    f"continuation line without a preceding key line: {raw_line!r}"
                )
            continuation = _strip_inline_comment(raw_line).strip()
            sections[current][last_key] += "\n" + continuation
            continue

        # Key line: must be inside a section (rule 10).
        if current is None:
            raise ValueError(f"key line before any section header: {raw_line!r}")

        # Rule 2: split on the FIRST '=' or ':', whichever comes first.
        eq = raw_line.find("=")
        colon = raw_line.find(":")
        candidates = [p for p in (eq, colon) if p != -1]
        if not candidates:
            raise ValueError(f"malformed line: {raw_line!r}")
        pos = min(candidates)
        key = raw_line[:pos].strip().lower()
        value = _extract_value(raw_line[pos + 1 :])
        if not key:
            raise ValueError(f"malformed line (empty key): {raw_line!r}")

        # Rule 7: later value wins.
        sections[current][key] = value
        last_key = key

    # Rule 8: DEFAULT's keys are inherited by every other section.
    defaults = sections.pop("DEFAULT", {})

    effective: dict[str, dict[str, str]] = {
        name: dict(defaults) for name in sections
    }
    for name, pairs in sections.items():
        effective[name].update(pairs)

    # Rule 9: recursive interpolation.
    resolving: set[tuple[str, str]] = set()

    def lookup(section: str, key: str) -> str:
        if section not in effective:
            raise KeyError(section)
        if key not in effective[section]:
            raise KeyError(key)
        return resolve(section, key)

    def resolve(section: str, key: str) -> str:
        marker = (section, key)
        if marker in resolving:
            raise ValueError(
                f"interpolation cycle detected involving {section}:{key}"
            )
        resolving.add(marker)
        try:
            raw = effective[section][key]

            def substitute(m: re.Match[str]) -> str:
                ref = m.group(1)
                if ":" in ref:
                    sec, k = ref.split(":", 1)
                    return lookup(sec, k.strip().lower())
                return lookup(section, ref.strip().lower())

            return _INTERP_RE.sub(substitute, raw)
        finally:
            resolving.discard(marker)

    for name, pairs in effective.items():
        for key in pairs:
            pairs[key] = resolve(name, key)

    return effective
